/**
 * One error contract for every command: a stable `code`, the exit code it
 * maps to, and an optional hint. With `--json`, the dispatcher prints the
 * error as `{"error":{...}}` on stdout; without it, as text on stderr.
 */
/** The exit code for each error code. 0 is success. */
export const EXIT_CODE_BY_ERROR = {
    failed: 1,
    aborted: 1,
    invalid_argument: 1,
    rate_limited: 1,
    unavailable: 1,
    usage: 2,
    pending: 3,
    not_found: 4,
    unauthenticated: 5,
    permission_denied: 5,
    conflict: 6,
    failed_precondition: 6,
};
/** The exit code table that `agent-sdk help` and `agent-sdk help --json` print. */
export const EXIT_CODES = [
    { exitCode: 0, meaning: "ok" },
    {
        exitCode: 1,
        meaning: "failed (also aborted, invalid_argument, rate_limited, unavailable)",
    },
    { exitCode: 2, meaning: "usage: bad command, flag, or argument" },
    { exitCode: 3, meaning: "pending: the work is still running" },
    { exitCode: 4, meaning: "not_found" },
    { exitCode: 5, meaning: "unauthenticated or permission_denied" },
    { exitCode: 6, meaning: "conflict or failed_precondition" },
];
export class CliError extends Error {
    constructor(message, options = {}) {
        super(message, { cause: options.cause });
        this.name = "CliError";
        this.code = options.code ?? "failed";
        this.hint = options.hint;
        this.details = options.details;
    }
    get exitCode() {
        return EXIT_CODE_BY_ERROR[this.code];
    }
}
/** A usage problem in one command's arguments. Exits 2 with a `--help` pointer. */
export class CliUsageError extends CliError {
    constructor(message, options = {}) {
        super(message, { code: "usage", hint: options.hint });
        this.name = "CliUsageError";
    }
}
/** The error code for an HTTP status from the Cursor backend or an agent server. */
export function errorCodeForStatus(status) {
    if (status === undefined || status === 0) {
        return "unavailable";
    }
    if (status === 400 || status === 422) {
        return "invalid_argument";
    }
    if (status === 401) {
        return "unauthenticated";
    }
    if (status === 403) {
        return "permission_denied";
    }
    if (status === 404) {
        return "not_found";
    }
    if (status === 409) {
        return "conflict";
    }
    if (status === 412 || status === 423) {
        return "failed_precondition";
    }
    if (status === 429) {
        return "rate_limited";
    }
    if (status >= 500) {
        return "unavailable";
    }
    return "failed";
}
/** The error code for a non-zero exit code, for commands that returned one. */
export function errorCodeForExitCode(exitCode) {
    switch (exitCode) {
        case 2:
            return "usage";
        case 3:
            return "pending";
        case 4:
            return "not_found";
        case 5:
            return "unauthenticated";
        case 6:
            return "conflict";
        default:
            return "failed";
    }
}
function httpStatusOf(error) {
    if (error === null || typeof error !== "object" || !("status" in error)) {
        return undefined;
    }
    const { status } = error;
    return typeof status === "number" ? status : undefined;
}
const HTTP_ERROR_NAMES = new Set([
    "DeployApiError",
    "CursorBackendError",
    "SlackProvisionApiError",
    "RemoteEvalError",
]);
/**
 * Map any thrown value to a {@link CliError}. Errors from the Cursor
 * backend clients keep their HTTP status as the code; anything else is
 * `failed`.
 */
export function toCliError(error) {
    if (error instanceof CliError) {
        return error;
    }
    if (error instanceof Error) {
        // A client error without a status never reached the server.
        const code = HTTP_ERROR_NAMES.has(error.name)
            ? errorCodeForStatus(httpStatusOf(error))
            : "failed";
        return new CliError(error.message, { code, cause: error });
    }
    return new CliError(String(error));
}
/** The JSON form of an error, as printed under `--json`. */
export function errorEnvelope(error) {
    return {
        error: {
            code: error.code,
            message: error.message,
            hint: error.hint,
            details: error.details,
        },
    };
}
